#!/usr/bin/env bash
# Fetch the layered-editor corpus (Krita, GIMP XCF, PaintShop Pro, PSD) into
# tools/corpus/igapA/ (gitignored, nothing here is committed), about 170 MB. Every file is
# checked against the SHA-256 below and recorded with its source and licence in
# tools/corpus/igapA/PROVENANCE.md.
#
# Usage: tools/corpus/fetch-layered.sh [GROUP...]
#   GROUP is a top folder of the manifest (kra, xcf, psp, psd). Default: all.
#
# Sources:
# * kra/krita-repo: Krita's own templates and test data (shape, clone, filter layers).
# * kra/bugs: .kra files attached to bugs.kde.org reports, saved by Krita with a merged
#   image (the oracle): vector, clone, fill, filter and file layers, filter masks, blend modes.
# * xcf/gimp-issues: .xcf files attached to GIMP issues, saved by GIMP 3 with layer
#   effects (GEGL filters). XCF stores no composite, so they have no in-file oracle.
# * psp: PaintShop Pro files from sembiance.com and the Paint.NET PSP plugin's tests.
# * psd/psd-tools: psd-tools test files (noise gradients, Color Lookup, layer effects).
#
# Downloads are data only: nothing fetched is executed. The tests that read the corpus skip
# when it is absent. Stops if free space drops below MIN_FREE_GB (default 8).
set -euo pipefail

ROOT=$(cd "$(dirname "$0")/../.." && pwd)
OUT=${SPECULAR_LAYERED_CORPUS:-$ROOT/tools/corpus/igapA}
MIN_FREE_GB=${MIN_FREE_GB:-8}
mkdir -p "$OUT"

die() { echo "fetch-layered: $*" >&2; exit 1; }

check_space() {
  local avail_kb
  avail_kb=$(df -Pk "$OUT" | awk 'NR==2{print $4}')
  if (( avail_kb < MIN_FREE_GB * 1024 * 1024 )); then
    die "only $((avail_kb / 1024 / 1024)) GB free (< ${MIN_FREE_GB} GB); stopping"
  fi
}

want() {
  (( ${#GROUPS_WANTED[@]} == 0 )) && return 0
  local g
  for g in "${GROUPS_WANTED[@]}"; do [[ $1 == "$g"/* ]] && return 0; done
  return 1
}

GROUPS_WANTED=("$@")
PROV="$OUT/PROVENANCE.md"
{
  echo "# Layered-editor corpus (tools/corpus/fetch-layered.sh)"
  echo
  echo "Not committed. Each file: path, SHA-256, source URL, licence, what it is."
  echo
  echo "| File | SHA-256 | Source | Licence | Note |"
  echo "|---|---|---|---|---|"
} > "$PROV"

fetched=0 failed=0
while IFS=$'\t' read -r dest url sum lic note; do
  [[ -z $dest || $dest == \#* ]] && continue
  path="$OUT/$dest"
  row=$(printf '| %s | `%s` | %s | %s | %s |' "$dest" "$sum" "$url" "$lic" "${note//|/\\|}")
  if ! want "$dest"; then
    [[ -s $path ]] && echo "$row" >> "$PROV"
    continue
  fi
  mkdir -p "$(dirname "$path")"
  if [[ ! -s $path ]] || ! echo "$sum  $path" | sha256sum -c --quiet - 2>/dev/null; then
    check_space
    if ! curl -fsSL --retry 3 -m 300 -A 'specular-corpus/1' -o "$path.part" "$url"; then
      echo "  failed: $url" >&2; rm -f "$path.part"; failed=$((failed + 1)); continue
    fi
    if ! echo "$sum  $path.part" | sha256sum -c --quiet - 2>/dev/null; then
      echo "  checksum mismatch: $dest ($url)" >&2; rm -f "$path.part"; failed=$((failed + 1)); continue
    fi
    mv "$path.part" "$path"
    fetched=$((fetched + 1))
  fi
  echo "$row" >> "$PROV"
  # A zip of sample files: its members unpacked beside it (data only, no paths kept).
  if [[ $dest == *.zip ]]; then
    python3 -I -c 'import os, sys, zipfile
z = zipfile.ZipFile(sys.argv[1])
for i in z.infolist():
    n = os.path.basename(i.filename)
    if n and not i.is_dir() and i.file_size < 64 << 20:
        open(os.path.join(os.path.dirname(sys.argv[1]), n), "wb").write(z.read(i))' "$path"
  fi
done <<'MANIFEST'
